import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] items = new long[n][2];
        for (int i = 0; i < n; i++) items[i][0] = nextLong();
        for (int i = 0; i < n; i++) items[i][1] = nextLong();
        Arrays.sort(items, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        // Max-heap by cost; among equal costs the smaller size first.
        PriorityQueue<long[]> heap = new PriorityQueue<>((x, y) -> x[1] != y[1] ? Long.compare(y[1], x[1]) : Long.compare(x[0], y[0]));
        long slot = 0, answer = 0;
        int i = 0;
        while (i < n || !heap.isEmpty()) {
            if (heap.isEmpty()) slot = Math.max(slot, items[i][0]);
            while (i < n && items[i][0] <= slot) heap.add(items[i++]);
            long[] top = heap.poll();
            answer += (slot - top[0]) * top[1];
            slot++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type item struct{ size, cost int64 }

// Max-heap by cost; among equal costs the smaller size first.
type costHeap []item

func (h costHeap) Len() int { return len(h) }
func (h costHeap) Less(i, j int) bool {
	if h[i].cost != h[j].cost {
		return h[i].cost > h[j].cost
	}
	return h[i].size < h[j].size
}
func (h costHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *costHeap) Push(x any)   { *h = append(*h, x.(item)) }
func (h *costHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	items := make([]item, n)
	for i := range items {
		items[i].size = nextInt()
	}
	for i := range items {
		items[i].cost = nextInt()
	}
	slices.SortFunc(items, func(x, y item) int {
		if x.size != y.size {
			if x.size < y.size {
				return -1
			}
			return 1
		}
		if x.cost < y.cost {
			return -1
		}
		if x.cost > y.cost {
			return 1
		}
		return 0
	})
	h := &costHeap{}
	slot, answer := int64(0), int64(0)
	i := 0
	for i < n || h.Len() > 0 {
		if h.Len() == 0 {
			slot = max(slot, items[i].size)
		}
		for i < n && items[i].size <= slot {
			heap.Push(h, items[i])
			i++
		}
		top := heap.Pop(h).(item)
		answer += (slot - top.size) * top.cost
		slot++
	}
	fmt.Println(answer)
}
